package authlete

// WithIDPURL sends IdP operations (service create/remove, audit) to idpURL
// instead of https://login.authlete.com. For DC and self-managed deployments;
// combine it with WithAPIServerID.
func WithIDPURL(idpURL string) SDKOption {
	return func(sdk *Authlete) {
		sdk.hooks.IDPRouting().IDPURL = idpURL
	}
}

// WithAPIServerID sets the apiServerId added to service create/remove
// requests that do not carry one. Authlete SaaS customers do not need it: it
// is derived from the server URL (us, jp, eu, br). DC deployments set it to
// the Cluster ID shown under Service Overview in the Management Console.
func WithAPIServerID(apiServerID int64) SDKOption {
	return func(sdk *Authlete) {
		sdk.hooks.IDPRouting().APIServerID = &apiServerID
	}
}

// registerAuthleteHooks is called from New, through
// .speakeasy/patches/authlete.go.patch, so every client gets IdP routing and
// the missing-serviceId check without passing any option.
func registerAuthleteHooks(sdk *Authlete) {
	sdk.hooks.IDPRouting()
}
